// (fixture ≤ 12) holds; prIndex maps state → raw REST list payload,
// absent, the legacy single-PR shape is served.
function listPayload(opts, pr, state) {
    if (opts.prIndex) return JSON.stringify(opts.prIndex[state || 'open'] || []);
