function resolveExisting(p, accept) {
    var rel = path.isAbsolute(String(p)) ? String(p) : String(p).replace(/^\.\//, '');
    var stripped = rel.indexOf('agents/') === 0 ? rel.substring('agents/'.length) : rel;
