        assert.equal(fx.crCalls[0].workspace, 'a', 'workspace is required by the Dart tool (merge leg crashed live 2026-09-29 without it)');
        assert.equal(fx.crCalls[0].repository, 'b', 'repository is required by the Dart tool');
