 * action()'s `labels.indexOf('x') !== -1` chains (gh-1040): each inline
 * chain added a decision to action's complexity, and the predicate reads
 * the same everywhere.
 */
function hasLabel(labels, wanted) {
    return labels.indexOf(wanted) !== -1;
